module arxmodel

import os

// GENERATED by scripts/gen_builtin.vsh with builtin.v; do not edit.

// builtin_files is every built-in text by the file it was made from.
const builtin_files = {
	'arxmodel/policy.toml': default_policy_text
	'arxmodel/automat.policy.toml': automat_policy_text
	'arxmodel/identity.toml': identity_text
	'flatxml/VENDORED': flatxml_vendored_text
	'v.mod': vmod_text
}

// The generated texts ARE the files they were made from: change one and forget
// scripts/gen_builtin.vsh, and this fails rather than the library carrying the old text.
fn test_the_builtin_texts_are_the_files() {
	for path, text in builtin_files {
		assert text == os.read_file(os.join_path(@VMODROOT, path))!, '${path} changed: v run scripts/gen_builtin.vsh'
	}
}
